import assert from 'node:assert/strict';
const {chromium}=await import(process.env.MX_PLAYWRIGHT_MODULE||'playwright-core');
const base=process.env.MX_AUDIT_URL||'http://127.0.0.1:4180';
const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',args:['--mute-audio']});
try {
  const page=await browser.newPage({viewport:{width:440,height:900},isMobile:true,hasTouch:true});
  const errors=[];page.on('pageerror',error=>errors.push(error.message));
  const openSettings=async()=>{
    await page.locator('.mx-table').waitFor();
    await page.locator('.mx-menu').click();
    await page.locator('.mx-menu-item[data-menu-action="UITexas_Setting"]').click();
    await page.locator('.mx-personal-settings').waitFor();
  };
  const tab=index=>page.locator('.mx-settings-tabs button').nth(index).click();
  const input=async(locator,value)=>locator.evaluate((element,value)=>{element.value=String(value);element.dispatchEvent(new Event('input',{bubbles:true}));},value);
  const quickMode=index=>page.locator('.mx-settings-quick > .mx-settings-modes:not(.mx-settings-submit-modes) button').nth(index).click();
  const shortcuts=()=>page.locator('.mx-settings-shortcut .mx-settings-pot-ratio').allTextContents();
  await page.goto(base+'/?table');await openSettings();
  await page.locator('.mx-settings-layouts button[data-layout="oval"]').click();
  await page.locator('.mx-settings-option-pair button').nth(1).click();
  await page.locator('.mx-settings-back[aria-label="gold"]').click();
  await page.locator('.mx-settings-deck[aria-label="2"]').click();
  await page.waitForFunction(()=>document.querySelector('.mx-settings-deck[aria-label="2"]')?.getAttribute('aria-pressed')==='true');
  const sizes=page.locator('.mx-settings-sizes input');
  for(const [index,value] of [4,0,3].entries())await input(sizes.nth(index),value);
  await page.locator('.mx-settings-desk[aria-label="12"]').click();
  await page.waitForFunction(()=>document.querySelector('.mx-settings-desk[aria-label="12"]')?.getAttribute('aria-pressed')==='true');
  await page.locator('.mx-settings-solid').click();
  await page.locator('.mx-settings-colors button[aria-label="#3296d2"]').click();
  await tab(1);
  await page.locator('.mx-settings-submit-modes button').first().click();
  await quickMode(0);await input(page.locator('.mx-settings-quick .mx-settings-range'),79);
  await quickMode(1);await input(page.locator('.mx-settings-quick .mx-settings-range'),47);
  await tab(2);
  const sound=page.locator('.mx-settings-system .mx-settings-switch');
  assert.equal(await sound.getAttribute('aria-checked'),'false');
  await sound.click();assert.equal(await sound.getAttribute('aria-checked'),'true');
  await page.reload();await openSettings();
  assert.equal(await page.locator('.mx-settings-layouts button[data-layout="oval"]').getAttribute('aria-pressed'),'true');
  assert.equal(await page.locator('.mx-settings-option-pair button').nth(1).getAttribute('aria-pressed'),'true');
  assert.equal(await page.locator('.mx-settings-back[aria-label="gold"]').getAttribute('aria-pressed'),'true');
  assert.equal(await page.locator('.mx-settings-deck[aria-label="2"]').getAttribute('aria-pressed'),'true');
  assert.deepEqual(await page.locator('.mx-settings-sizes output').allTextContents(),['110%','90%','105%']);
  assert.equal(await page.locator('.mx-settings-solid').getAttribute('aria-pressed'),'true');
  assert.equal(await page.locator('.mx-settings-colors button[aria-label="#3296d2"]').getAttribute('aria-pressed'),'true');
  await tab(1);
  assert.equal(await page.locator('.mx-settings-submit-modes button').first().getAttribute('aria-pressed'),'true');
  assert.equal((await shortcuts()).length,5);assert.equal((await shortcuts())[0],'47%');
  await quickMode(0);assert.equal((await shortcuts()).length,3);assert.equal((await shortcuts())[0],'79%');
  await quickMode(1);assert.equal((await shortcuts())[0],'47%');
  await tab(2);assert.equal(await sound.getAttribute('aria-checked'),'true');
  await sound.click();await page.reload();await openSettings();await tab(2);
  assert.equal(await sound.getAttribute('aria-checked'),'false');
  await tab(0);await page.locator('.mx-settings-desk[aria-label="12"]').click();
  await page.waitForFunction(()=>document.querySelector('.mx-settings-desk[aria-label="12"]')?.getAttribute('aria-pressed')==='true');
  await page.reload();await openSettings();
  assert.equal(await page.locator('.mx-settings-desk[aria-label="12"]').getAttribute('aria-pressed'),'true');
  assert.equal(await page.locator('.mx-settings-solid').getAttribute('aria-pressed'),'false');
  assert.deepEqual(errors,[]);
  console.log('All table setting controls restored after page reload, including both shortcut modes, both desk styles and sound on/off.');
} finally {await browser.close();}
